-- NexusMaster Interfone: no physical access commands are generated by this module.
CREATE TABLE IF NOT EXISTS intercom_units (client_id TEXT NOT NULL,id TEXT NOT NULL,label TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(client_id,id));
CREATE TABLE IF NOT EXISTS intercom_unit_members (client_id TEXT NOT NULL,unit_id TEXT NOT NULL,user_id TEXT NOT NULL,PRIMARY KEY(client_id,unit_id,user_id));
CREATE TABLE IF NOT EXISTS intercom_calls (id TEXT PRIMARY KEY,client_id TEXT NOT NULL,unit_id TEXT NOT NULL,reason TEXT NOT NULL,token_hash TEXT NOT NULL,status TEXT NOT NULL,created_at INTEGER NOT NULL,expires INTEGER NOT NULL,answered_at INTEGER,answered_by TEXT,ended_at INTEGER,offer_sdp TEXT,answer_sdp TEXT);
CREATE INDEX IF NOT EXISTS intercom_calls_unit ON intercom_calls(client_id,unit_id,status,expires);
CREATE TABLE IF NOT EXISTS intercom_rate_limits(key TEXT NOT NULL,bucket INTEGER NOT NULL,n INTEGER NOT NULL,PRIMARY KEY(key,bucket));